def ensure_image_assets() -> None:
    ASSET_DIR.mkdir(exist_ok=True)
    for filename, data in EMBEDDED_ASSETS.items():
        target = ASSET_DIR / filename
        if not target.exists():
            target.write_bytes(base64.b64decode(data))

