# ============================================================
# Math + simulation helpers (single-level)
# ============================================================

def gaussian(x, mu, precision):
    precision = max(float(precision), 1e-6)
    sigma = 1.0 / np.sqrt(precision)
    return np.exp(-0.5 * ((x - mu) / sigma) ** 2) / (sigma * np.sqrt(2 * np.pi))


def posterior_mean(prior_mean, prior_precision, observation, sensory_precision):
    return (prior_precision * prior_mean + sensory_precision * observation) / (
        prior_precision + sensory_precision
    )


def plot_bayesian_update(prior_mean, prior_precision, observation, sensory_precision):
    post_precision = prior_precision + sensory_precision
    post_mean = posterior_mean(prior_mean, prior_precision, observation, sensory_precision)
    alpha = sensory_precision / post_precision
    prediction_error = observation - prior_mean

    x_min = min(prior_mean, observation, post_mean) - 18
    x_max = max(prior_mean, observation, post_mean) + 18
    x = np.linspace(x_min, x_max, 600)

    fig = go.Figure()
    fig.add_trace(go.Scatter(
        x=x, y=gaussian(x, prior_mean, prior_precision),
        mode="lines", fill="tozeroy", name="prior",
        line=dict(color=PALETTE["deep"]),
    ))
    fig.add_trace(go.Scatter(
        x=x, y=gaussian(x, observation, sensory_precision),
        mode="lines", fill="tozeroy", name="evidence",
        line=dict(color=PALETTE["warm"]),
    ))
    fig.add_trace(go.Scatter(
        x=x, y=gaussian(x, post_mean, post_precision),
        mode="lines", fill="tozeroy", name="updated belief",
        line=dict(color=PALETTE["mid"]),
    ))
    fig.add_vline(x=prior_mean, line_dash="dot", annotation_text="prior", annotation_position="top left")
    fig.add_vline(x=observation, line_dash="dot", annotation_text="evidence", annotation_position="top right")
    fig.add_vline(x=post_mean, line_dash="solid", annotation_text="updated", annotation_position="bottom right")
    fig.update_layout(
        height=420,
        margin=dict(l=20, r=20, t=85, b=35),
        title=dict(
            text=f"Single update: updated belief = {post_mean:.1f}",
            x=0.5,
            xanchor="center",
            font=dict(size=16),
        ),
        xaxis_title="Body-size estimate (waist, cm)",
        yaxis_title="Belief density",
        legend=dict(
            orientation="h",
            yanchor="bottom",
            y=1.12,
            xanchor="left",
            x=0,
            font=dict(size=11),
        ),
    )
    return fig, post_mean, alpha, prediction_error


def simulate_belief_evolution(true_value, sensory_noise_sd, alpha, initial_belief, n_trials, seed):
    rng = np.random.default_rng(seed)
    observations = rng.normal(true_value, sensory_noise_sd, n_trials)
    belief = float(initial_belief)
    beliefs = [belief]
    pred_errors = []
    for obs in observations:
        pe = obs - belief
        belief = belief + alpha * pe
        pred_errors.append(pe)
        beliefs.append(belief)
    return observations, np.array(beliefs), np.array(pred_errors)


def plot_belief_evolution(true_value, sensory_noise_sd, alpha, initial_belief, n_trials, seed):
    observations, beliefs, pred_errors = simulate_belief_evolution(
        true_value, sensory_noise_sd, alpha, initial_belief, n_trials, seed
    )
    trials_obs = np.arange(1, n_trials + 1)
    trials_belief = np.arange(0, n_trials + 1)

    fig = go.Figure()
    fig.add_hline(y=true_value, line_dash="dash", line_color="rgba(120,120,120,0.75)", annotation_text="true value", annotation_position="top left")
    fig.add_trace(go.Scatter(
        x=trials_obs, y=observations, mode="markers",
        name="sensory observations",
        marker=dict(color=PALETTE["warm"], size=6, opacity=0.45),
    ))
    fig.add_trace(go.Scatter(
        x=trials_belief, y=beliefs, mode="lines+markers",
        name="internal estimate",
        line=dict(color=PALETTE["deep"], width=2.6),
        marker=dict(color=PALETTE["deep"], size=4),
    ))
    fig.update_layout(
        height=440,
        margin=dict(l=20, r=20, t=75, b=35),
        title=dict(
            text=f"Repeated updating across trials · final estimate = {beliefs[-1]:.1f}",
            x=0.5,
            xanchor="center",
            font=dict(size=16),
        ),
        xaxis_title="Trial",
        yaxis_title="Estimated value",
        legend=dict(orientation="h", yanchor="bottom", y=1.08, xanchor="left", x=0, font=dict(size=11)),
    )
    return fig


def precision_to_sd(precision: float) -> float:
    return 1.0 / np.sqrt(max(float(precision), 1e-6))


def simulate_precision_weighted_evolution(true_value, initial_belief, prior_precision, sensory_precision, n_trials, seed):
    rng = np.random.default_rng(seed)
    sensory_sd = precision_to_sd(sensory_precision)
    prior_sd = precision_to_sd(prior_precision)
    observations = rng.normal(true_value, sensory_sd, n_trials)
    alpha = sensory_precision / (sensory_precision + prior_precision)

    belief = float(initial_belief)
    beliefs = [belief]
    prediction_errors = []
    for obs in observations:
        pe = obs - belief
        belief = belief + alpha * pe
        prediction_errors.append(pe)
        beliefs.append(belief)

    return observations, np.array(beliefs), np.array(prediction_errors), alpha, prior_sd, sensory_sd


def plot_precision_weighted_belief_evolution(true_value, initial_belief, prior_precision, sensory_precision, n_trials, seed):
    observations, beliefs, pes, alpha, prior_sd, sensory_sd = simulate_precision_weighted_evolution(
        true_value, initial_belief, prior_precision, sensory_precision, n_trials, seed
    )
    trials_obs = np.arange(1, n_trials + 1)
    trials_belief = np.arange(0, n_trials + 1)

    fig = go.Figure()
    fig.add_hline(y=true_value, line_dash="dash", annotation_text="average sensory value", annotation_position="top left")
    fig.add_hline(y=initial_belief, line_dash="dot", annotation_text="starting belief", annotation_position="bottom left")
    fig.add_trace(go.Scatter(
        x=trials_obs, y=observations, mode="markers",
        name="Sensory observations",
        marker=dict(color=PALETTE["warm"], size=6, opacity=0.60),
    ))
    fig.add_trace(go.Scatter(
        x=trials_belief, y=beliefs, mode="lines+markers",
        name="Internal belief over time",
        line=dict(color=PALETTE["deep"], width=2.5),
        marker=dict(color=PALETTE["deep"], size=5),
    ))
    fig.update_layout(
        height=440,
        margin=dict(l=20, r=20, t=70, b=30),
        title=(
            f"Sensory weight α = {alpha:.2f}  ·  final belief = {beliefs[-1]:.1f}  ·  "
            f"gap from average sensory value = {beliefs[-1] - true_value:+.1f}"
        ),
        xaxis_title="Observation number",
        yaxis_title="Estimated body value",
        legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="left", x=0),
    )
    return fig, alpha, prior_sd, sensory_sd, beliefs[-1], pes.mean()


# ============================================================
# Linear-regression teaching example
# ============================================================

def make_synthetic_body_data(n=180, seed=10):
    """Synthetic teaching data: shows correlations, redundancy, and same-score-different-mechanism."""
    rng = np.random.default_rng(seed)
    body_prior_bias = rng.normal(0, 1, n)
    uncertainty     = rng.normal(0, 1, n)
    arousal         = rng.normal(0, 1, n)
    bmi             = rng.normal(0, 1, n)

    body_estimation_error = 0.85 * body_prior_bias + 0.25 * uncertainty + rng.normal(0, 0.35, n)
    confidence            = -0.65 * uncertainty - 0.25 * body_prior_bias + rng.normal(0, 0.40, n)
    reaction_time         =  0.75 * uncertainty + 0.45 * body_prior_bias + rng.normal(0, 0.35, n)
    task_difficulty       =  0.70 * uncertainty + 0.20 * arousal + rng.normal(0, 0.40, n)
    heart_rate            =  0.72 * arousal + 0.40 * uncertainty + rng.normal(0, 0.40, n)

    body_dissatisfaction = (
        55 + 10.5 * body_prior_bias + 6.5 * uncertainty + 3.0 * arousal + 2.0 * bmi + rng.normal(0, 3.2, n)
    )
    return pd.DataFrame({
        "body_estimation_error": body_estimation_error,
        "reaction_time":         reaction_time,
        "confidence":            confidence,
        "task_difficulty":       task_difficulty,
        "heart_rate":            heart_rate,
        "bmi":                   bmi,
        "body_dissatisfaction":  body_dissatisfaction,
        "hidden_prior_bias":     body_prior_bias,
        "hidden_uncertainty":    uncertainty,
        "hidden_arousal":        arousal,
    })


def standardize(s):
    return (s - s.mean()) / s.std(ddof=0)


def fit_linear_regression(df, predictors, target="body_dissatisfaction"):
    X = np.column_stack([np.ones(len(df))] + [standardize(df[p]).values for p in predictors])
    y = df[target].values
    beta = np.linalg.lstsq(X, y, rcond=None)[0]
    yhat = X @ beta
    r2 = 1 - np.sum((y - yhat) ** 2) / np.sum((y - y.mean()) ** 2)
    coefs = pd.DataFrame({"predictor": ["intercept"] + predictors, "coefficient": beta})
    return coefs, yhat, r2


def plot_corrs(df, variables):
    corr = df[variables + ["body_dissatisfaction"]].corr()["body_dissatisfaction"].drop("body_dissatisfaction")
    corr = corr.sort_values(key=np.abs, ascending=True)
    fig = go.Figure(go.Bar(
        x=corr.values, y=corr.index, orientation="h",
        marker=dict(color=PALETTE["mid"]),
    ))
    fig.update_layout(
        height=380,
        title="Which observed variables correlate with body dissatisfaction?",
        xaxis_title="Correlation with body dissatisfaction",
        yaxis_title="",
        margin=dict(l=20, r=20, t=55, b=30),
    )
    return fig, corr.sort_values(key=np.abs, ascending=False)


def plot_regression_coefficients(coefs):
    c = coefs[coefs["predictor"] != "intercept"].copy().sort_values("coefficient")
    fig = go.Figure(go.Bar(
        x=c["coefficient"], y=c["predictor"], orientation="h",
        marker=dict(color=PALETTE["deep"]),
    ))
    fig.update_layout(
        height=320,
        title="Linear-regression coefficients (standardised predictors)",
        xaxis_title="Coefficient",
        yaxis_title="",
        margin=dict(l=20, r=20, t=55, b=30),
    )
    return fig


def person_contribution_plot(coefs, persons_df, predictors):
    beta = coefs.set_index("predictor")["coefficient"]
    contrib = []
    for person_name, row in persons_df.iterrows():
        for p in predictors:
            contrib.append({"person": person_name, "component": p, "contribution": row[p] * beta[p]})
        contrib.append({"person": person_name, "component": "intercept", "contribution": beta["intercept"]})
    out = pd.DataFrame(contrib)
    fig = px.bar(
        out, x="person", y="contribution", color="component", barmode="relative",
        title="Same predicted score, different contributions",
        color_discrete_sequence=[PALETTE["deep"], PALETTE["mid"], PALETTE["warm"], PALETTE["soft"]],
    )
    fig.update_layout(height=420, xaxis_title="", yaxis_title="Contribution to predicted body dissatisfaction",
                      margin=dict(l=20, r=20, t=55, b=30))
    return fig, out


# ============================================================
# Hierarchical predictive coding (4-level body-image inspired)
# ============================================================

# Generative weights:
# L1 (body parts: waist, thigh, arm) → L0 sensory features (width/contour pairs)
W1 = np.array([
    [0.6, 0.0, 0.0],   # waist width
    [0.4, 0.0, 0.0],   # waist contour
    [0.0, 0.6, 0.0],   # thigh width
    [0.0, 0.4, 0.0],   # thigh contour
    [0.0, 0.0, 0.6],   # arm width
    [0.0, 0.0, 0.4],   # arm contour
])
# L2 (integrated shape) → L1 (body parts)
W2 = np.array([[0.35], [0.25], [0.10]])
# L3 (abstract belief) → L2 (shape)
W3 = np.array([[1.0]])


def step_hierarchy(s, r1, r2, r3, prior_L3, pi0, pi1, pi2, pi3, alpha):
    pred_L0 = W1 @ r1
    pred_L1 = (W2 @ r2).flatten()
    pred_L2 = (W3 @ r3).flatten()

    e0 = s - pred_L0
    e1 = r1 - pred_L1
    e2 = r2 - pred_L2
    e3 = r3 - prior_L3

    dr1 = alpha * (pi0 * (W1.T @ e0) - pi1 * e1)
    dr2 = alpha * (pi1 * (W2.T @ e1).flatten() - pi2 * e2)
    dr3 = alpha * (pi2 * (W3.T @ e2).flatten() - pi3 * e3)

    return r1 + dr1, r2 + dr2, r3 + dr3, {"e0": e0, "e1": e1, "e2": e2, "e3": e3}


def run_hierarchy(true_body=(70.0, 55.0, 30.0),
                  prior_L3=280.0,
                  init=(75.0, 60.0, 35.0, 200.0, 200.0),
                  n_trials=120, sensory_noise=2.5,
                  pi0=1.0, pi1=0.4, pi2=0.4, pi3=0.6, alpha=0.15, seed=1):
    rng = np.random.default_rng(seed)
    true_r1 = np.array(true_body, dtype=float)
    true_s = W1 @ true_r1

    r1 = np.array(init[:3], dtype=float)
    r2 = np.array([init[3]], dtype=float)
    r3 = np.array([init[4]], dtype=float)
    p3 = np.array([prior_L3], dtype=float)

    h1, h2, h3 = [r1.copy()], [r2.copy()], [r3.copy()]
    for _ in range(n_trials):
        s = true_s + rng.normal(0.0, sensory_noise, size=6)
        r1, r2, r3, _ = step_hierarchy(s, r1, r2, r3, p3, pi0, pi1, pi2, pi3, alpha)
        h1.append(r1.copy())
        h2.append(r2.copy())
        h3.append(r3.copy())
    return np.array(h1), np.array(h2).reshape(-1), np.array(h3).reshape(-1), true_r1


def hierarchy_plot(prior_L3, pi0, pi3, alpha, n_trials, sensory_noise, seed):
    h1, h2, h3, true_r1 = run_hierarchy(
        true_body=(70, 55, 30), prior_L3=prior_L3, init=(75, 60, 35, 200, 200),
        n_trials=n_trials, sensory_noise=sensory_noise,
        pi0=pi0, pi1=0.4, pi2=0.4, pi3=pi3, alpha=alpha, seed=seed,
    )
    trials = np.arange(len(h1))

    fig = go.Figure()
    fig.add_trace(go.Scatter(x=trials, y=h1[:, 0], mode="lines",
                             name="L1 waist estimate",  line=dict(color=PALETTE["deep"])))
    fig.add_trace(go.Scatter(x=trials, y=h1[:, 1], mode="lines",
                             name="L1 thigh estimate",  line=dict(color=PALETTE["mid"])))
    fig.add_trace(go.Scatter(x=trials, y=h1[:, 2], mode="lines",
                             name="L1 arm estimate",    line=dict(color="#7FB3D5")))
    fig.add_trace(go.Scatter(x=trials, y=h2, mode="lines",
                             name="L2 integrated shape", line=dict(color=PALETTE["warm"]), yaxis="y2"))
    fig.add_trace(go.Scatter(x=trials, y=h3, mode="lines",
                             name="L3 abstract belief",  line=dict(color="#8b5e3c", dash="dot"), yaxis="y2"))
    fig.add_hline(y=true_r1[0], line_dash="dash", annotation_text="true waist", annotation_position="top left")
    fig.update_layout(
        height=520,
        title=f"Hierarchy simulation  ·  final waist estimate = {h1[-1,0]:.1f} cm  ·  truth = {true_r1[0]:.0f} cm",
        xaxis_title="Trial",
        yaxis=dict(title="L1 body-part estimates (cm)"),
        yaxis2=dict(title="L2 / L3 abstract units", overlaying="y", side="right"),
        legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="left", x=0),
        margin=dict(l=20, r=20, t=60, b=30),
    )
    return fig


def healthy_vs_bid_plot(n_trials=120, seed=7):
    rng = np.random.default_rng(seed)
    true_body = (70.0, 55.0, 30.0)
    true_r1 = np.array(true_body)
    true_s = W1 @ true_r1
    noise = 2.5
    obs_seq = np.array([true_s + rng.normal(0.0, noise, 6) for _ in range(n_trials)])

    def simulate(prior_L3, pi0, pi3, alpha=0.15):
        r1 = np.array([75.0, 60.0, 35.0])
        r2 = np.array([200.0])
        r3 = np.array([200.0])
        p3 = np.array([prior_L3])
        hist = [r1.copy()]
        for s in obs_seq:
            r1, r2, r3, _ = step_hierarchy(s, r1, r2, r3, p3,
                                           pi0=pi0, pi1=0.4, pi2=0.4, pi3=pi3, alpha=alpha)
            hist.append(r1.copy())
        return np.array(hist)

    h_healthy = simulate(prior_L3=215.0, pi0=1.0, pi3=0.05)
    h_bid     = simulate(prior_L3=290.0, pi0=0.4, pi3=1.2)
    trials = np.arange(n_trials + 1)

    fig = go.Figure()
    fig.add_trace(go.Scatter(x=trials, y=h_healthy[:, 0], mode="lines",
                             name="Healthy-like: flexible prior + reliable senses",
                             line=dict(color=PALETTE["mid"], width=2.4)))
    fig.add_trace(go.Scatter(x=trials, y=h_bid[:, 0], mode="lines",
                             name="BID-like: rigid prior + low sensory precision",
                             line=dict(color=PALETTE["warm"], width=2.4)))
    fig.add_hline(y=70, line_dash="dash", annotation_text="true waist", annotation_position="top left")
    fig.update_layout(
        height=440,
        title="Same sensory observations, different hidden mechanisms",
        xaxis_title="Trial",
        yaxis_title="L1 waist estimate (cm)",
        legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="left", x=0),
        margin=dict(l=20, r=20, t=55, b=30),
    )
    return fig





def three_personalities_plot(true_value=70.0, sensory_noise_sd=3.0, initial_belief=78.0, n_trials=50, seed=2):
    rng = np.random.default_rng(seed)
    observations = rng.normal(true_value, sensory_noise_sd, n_trials)
    profiles = [
        ("Stubborn believer\nstrong prior, low sensory trust", 0.03, PALETTE["warm"]),
        ("Balanced observer\nmoderate updating", 0.20, PALETTE["deep"]),
        ("Sensory-driven observer\nhigh sensory trust", 0.55, PALETTE["mid"]),
    ]
    fig = go.Figure()
    trials = np.arange(1, n_trials + 1)
    fig.add_trace(go.Scatter(
        x=trials, y=observations, mode="markers", name="Same noisy observations",
        marker=dict(color="rgba(80,80,80,0.35)", size=6),
    ))
    fig.add_hline(y=true_value, line_dash="dash", annotation_text="true value", annotation_position="top left")

    for label, alpha, color in profiles:
        belief = initial_belief
        beliefs = [belief]
        for obs in observations:
            belief = belief + alpha * (obs - belief)
            beliefs.append(belief)
        fig.add_trace(go.Scatter(
            x=np.arange(0, n_trials + 1), y=beliefs, mode="lines",
            name=label, line=dict(color=color, width=3),
        ))

    fig.update_layout(
        height=430,
        title="Same observations, three different updating styles",
        xaxis_title="Observation number",
        yaxis_title="Internal estimate",
        legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="left", x=0),
        margin=dict(l=20, r=20, t=70, b=30),
    )
    return fig


def plot_predictive_coding_profiles_subplots(
    true_value=70.0,
    initial_belief=78.0,
    sensory_noise_sd=3.0,
    n_trials=50,
    alpha_stubborn=0.06,
    alpha_balanced=0.20,
    alpha_sensory=0.50,
    seed=2,
):
    """Interactive multi-trial plot for the Bayes → predictive-coding bridge.

    The same noisy observations are shown in three panels. Each panel differs only
    in how much the internal estimate changes after each prediction error. This makes
    it easy to explain when we have moved from a single Bayesian update to a repeated
    predictive-coding loop across trials.
    """
    rng = np.random.default_rng(seed)
    observations = rng.normal(true_value, sensory_noise_sd, n_trials)
    trial_numbers = np.arange(1, n_trials + 1)

    profiles = [
        ("Stubborn believer", "strong prior, low trust in senses", alpha_stubborn, "#2C974B"),
        ("Balanced observer", "moderate trust", alpha_balanced, PALETTE["deep"]),
        ("Anxious empiricist", "weak prior, high trust in senses", alpha_sensory, PALETTE["mid"]),
    ]

    fig = make_subplots(
        rows=1,
        cols=3,
        shared_yaxes=True,
        horizontal_spacing=0.08,
        subplot_titles=[f"<b>{name}</b>" for name, _, _, _ in profiles],
    )

    summary_rows = []

    for col, (name, subtitle, alpha, color) in enumerate(profiles, start=1):
        belief = float(initial_belief)
        beliefs = [belief]
        prediction_errors = []
        for obs in observations:
            pe = obs - belief
            belief = belief + alpha * pe
            beliefs.append(belief)
            prediction_errors.append(pe)

        fig.add_trace(
            go.Scatter(
                x=trial_numbers,
                y=observations,
                mode="markers",
                name="sensory observations",
                showlegend=False,
                marker=dict(color="rgba(229,142,46,0.35)", size=6),
            ),
            row=1, col=col,
        )

        fig.add_trace(
            go.Scatter(
                x=np.arange(0, n_trials + 1),
                y=beliefs,
                mode="lines",
                name="internal estimate",
                showlegend=False,
                line=dict(color=color, width=3),
            ),
            row=1, col=col,
        )

        fig.add_hline(
            y=true_value,
            line_dash="dash",
            line_color="rgba(120,120,120,0.75)",
            row=1, col=col,
        )

        xref = "x domain" if col == 1 else f"x{col} domain"
        fig.add_annotation(
            x=0.5,
            y=1.035,
            xref=xref,
            yref="paper",
            text=subtitle,
            showarrow=False,
            font=dict(size=11, color=PALETTE["muted"]),
        )

        fig.update_xaxes(title_text="Trial", row=1, col=col)

        summary_rows.append({
            "Profile": name,
            "Update rate (alpha)": round(alpha, 2),
            "Final estimate": round(float(beliefs[-1]), 1),
            "Gap from true value": round(float(beliefs[-1] - true_value), 1),
            "Mean prediction error": round(float(np.mean(prediction_errors)), 1),
        })

    for ann in fig.layout.annotations[:3]:
        ann.font = dict(size=13, color=PALETTE["ink"])

    fig.update_yaxes(title_text="Estimated value", row=1, col=1)
    fig.update_layout(
        height=500,
        title=dict(
            text="Same observations — three different ways of integrating prior and senses",
            x=0.5,
            xanchor="center",
            y=0.99,
        ),
        margin=dict(l=20, r=20, t=120, b=40),
    )

    return fig, pd.DataFrame(summary_rows)


def bid_notebook_style_plot(true_body=70.0, biased_prior=80.0, sensory_noise_sd=3.0, alpha=0.10, n_trials=80, seed=3):
    rng = np.random.default_rng(seed)
    observations = rng.normal(true_body, sensory_noise_sd, n_trials)
    belief = biased_prior
    beliefs = [belief]
    for obs in observations:
        belief = belief + alpha * (obs - belief)
        beliefs.append(belief)

    trials = np.arange(1, n_trials + 1)
    fig = go.Figure()
    fig.add_trace(go.Scatter(
        x=trials, y=observations, mode="markers", name="Noisy sensory observations",
        marker=dict(color="rgba(80,80,80,0.35)", size=6),
    ))
    fig.add_trace(go.Scatter(
        x=np.arange(0, n_trials + 1), y=beliefs, mode="lines+markers", name="Internal belief",
        line=dict(color=PALETTE["deep"], width=3), marker=dict(size=4),
    ))
    fig.add_hline(y=true_body, line_dash="dash", annotation_text="true body value", annotation_position="top left")
    fig.add_hline(y=biased_prior, line_dash="dot", annotation_text="biased prior", annotation_position="bottom left")
    fig.update_layout(
        height=430,
        title=f"Biased prior + repeated evidence · final belief = {beliefs[-1]:.1f}",
        xaxis_title="Observation number",
        yaxis_title="Estimated body value",
        legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="left", x=0),
        margin=dict(l=20, r=20, t=70, b=30),
    )
    return fig



def plot_rigid_prior_comparison(true_body=70.0, biased_prior=80.0, sensory_noise_sd=3.0, n_trials=80, seed=11):
    """Compare flexible, moderate, and rigid updating from the same observations.

    This is used on Slide 9 to combine the old repeated-observation demo with the
    Bayesian-to-predictive-coding bridge.  The key message is that repeated sensory
    disagreement is not enough if the prior is too rigid / too heavily trusted.
    """
    rng = np.random.default_rng(seed)
    observations = rng.normal(true_body, sensory_noise_sd, n_trials)
    trials_obs = np.arange(1, n_trials + 1)

    profiles = [
        ("flexible prior  (alpha = 0.40)", 0.40, "#2C974B"),
        ("moderate rigid  (alpha = 0.10)", 0.10, "#E58E2E"),
        ("very rigid  (alpha = 0.02)", 0.02, "#D73A31"),
    ]

    fig = go.Figure()
    fig.add_trace(go.Scatter(
        x=trials_obs,
        y=observations,
        mode="markers",
        name="sensory observations",
        marker=dict(color="rgba(229,142,46,0.28)", size=6),
    ))
    fig.add_hline(y=true_body, line_dash="dash", line_color="rgba(90,90,90,0.75)",
                  annotation_text=f"true body value = {true_body:.0f}", annotation_position="top left")
    fig.add_hline(y=biased_prior, line_dash="dot", line_color="#5B9BD5",
                  annotation_text=f"biased prior = {biased_prior:.0f}", annotation_position="top left")

    summary_rows = []
    for label, alpha, color in profiles:
        belief = float(biased_prior)
        beliefs = [belief]
        prediction_errors = []
        for obs in observations:
            pe = obs - belief
            belief = belief + alpha * pe
            prediction_errors.append(pe)
            beliefs.append(belief)
        final_estimate = float(beliefs[-1])
        summary_rows.append({
            "Profile": label.replace("  ", " "),
            "Sensory weight alpha": alpha,
            "Final internal estimate": round(final_estimate, 1),
            "Final gap from true value": round(final_estimate - true_body, 1),
            "Mean prediction error": round(float(np.mean(prediction_errors)), 1),
        })
        fig.add_trace(go.Scatter(
            x=np.arange(0, n_trials + 1),
            y=beliefs,
            mode="lines",
            name=label,
            line=dict(color=color, width=3),
        ))

    fig.update_layout(
        height=440,
        title="A rigid biased prior keeps the internal body estimate stuck — even when the senses consistently disagree",
        xaxis_title="Observation number",
        yaxis_title="Internal body estimate",
        legend=dict(orientation="v", yanchor="top", y=1.0, xanchor="left", x=1.02),
        margin=dict(l=20, r=185, t=70, b=30),
    )
    return fig, pd.DataFrame(summary_rows)


# ============================================================
# Step controls (PowerPoint-style reveal)
# ============================================================

def reset_step_when_slide_changes(selected_slide: str) -> None:
    if "current_slide" not in st.session_state:
        st.session_state.current_slide = selected_slide
        st.session_state.slide_step = 1
    if st.session_state.current_slide != selected_slide:
        st.session_state.current_slide = selected_slide
        st.session_state.slide_step = 1


def step_controls(max_steps: int) -> int:
    if "slide_step" not in st.session_state:
        st.session_state.slide_step = 1
    with st.container():
        st.markdown("<div class='step-bar'>", unsafe_allow_html=True)
        c1, c2, c3, c4 = st.columns([1, 1.2, 1, 1])
        with c1:
            if st.button("⬅ Back", use_container_width=True, key=f"back_{st.session_state.current_slide}"):
                st.session_state.slide_step = max(1, st.session_state.slide_step - 1)
        with c2:
            st.markdown(
                f"<div style='text-align:center; padding-top:0.45rem; font-weight:600;'>"
                f"Step {st.session_state.slide_step} / {max_steps}</div>",
                unsafe_allow_html=True,
            )
        with c3:
            if st.button("Next ➡", use_container_width=True, key=f"next_{st.session_state.current_slide}"):
                st.session_state.slide_step = min(max_steps, st.session_state.slide_step + 1)
        with c4:
            if st.button("Show all", use_container_width=True, key=f"all_{st.session_state.current_slide}"):
                st.session_state.slide_step = max_steps
        st.markdown("</div>", unsafe_allow_html=True)
    return st.session_state.slide_step


